 var tags []TagModel;if e=db.Select(&tags,"SELECT * FROM tags ORDER BY id");e!=nil{return e};tm:=map[int64]Tag{};for _,t:=range tags{v:=Tag{ID:t.ID,Name:t.Name};tm[t.ID]=v;s.Tags=append(s.Tags,v)}
 var ls []LivestreamModel;if e=db.Select(&ls,"SELECT * FROM livestreams");e!=nil{return e};for _,l:=range ls{s.Streams[l.ID]=&StreamData{Model:l,Tags:[]Tag{}}}
 var lt []LivestreamTagModel;if e=db.Select(&lt,"SELECT * FROM livestream_tags ORDER BY id");e!=nil{return e};for _,t:=range lt{if l:=s.Streams[t.LivestreamID];l!=nil{l.Tags=append(l.Tags,tm[t.TagID])}}
