 var rs []ReactionModel;if e=db.Select(&rs,"SELECT * FROM reactions");e!=nil{return e};for _,r:=range rs{s.Reactions[r.ID]=r}
 var ws []NGWord;if e=db.Select(&ws,"SELECT * FROM ng_words");e!=nil{return e};for _,w:=range ws{s.Words[w.ID]=w}
 var reps []LivecommentReportModel;if e=db.Select(&reps,"SELECT * FROM livecomment_reports");e!=nil{return e};for _,r:=range reps{s.Reports[r.ID]=r}
 var vs []struct{ID int64 `db:"id"`;UserID int64 `db:"user_id"`;LivestreamID int64 `db:"livestream_id"`;CreatedAt int64 `db:"created_at"`};if e=db.Select(&vs,"SELECT * FROM livestream_viewers_history");e!=nil{return e};for _,v:=range vs{if s.Viewers[v.LivestreamID]==nil{s.Viewers[v.LivestreamID]=map[int64][]int64{}};s.Viewers[v.LivestreamID][v.UserID]=append(s.Viewers[v.LivestreamID][v.UserID],v.CreatedAt)}
