 for id:=range st.Users{maxID("user",id);agg(userStats,id)}
 for id,s:=range st.Streams{maxID("stream",id);indexStream(s)}
 sort.Slice(streamIDs,func(i,j int)bool{return streamIDs[i]<streamIDs[j]});for _,ids:=range userStreams{sort.Slice(ids,func(i,j int)bool{return ids[i]<ids[j]})};for _,ids:=range tagStreams{sort.Slice(ids,func(i,j int)bool{return ids[i]<ids[j]})}
 for id,c:=range st.Comments{maxID("comment",id);indexComment(c,1);commentIDs[c.LivestreamID]=append(commentIDs[c.LivestreamID],id)}
 for _,ids:=range commentIDs{sort.Slice(ids,func(i,j int)bool{a,b:=st.Comments[ids[i]],st.Comments[ids[j]];if a.CreatedAt==b.CreatedAt{return a.ID<b.ID};return a.CreatedAt<b.CreatedAt})}
 for id,r:=range st.Reactions{maxID("reaction",id);indexReaction(r);reactionIDs[r.LivestreamID]=append(reactionIDs[r.LivestreamID],id)}
 for _,ids:=range reactionIDs{sort.Slice(ids,func(i,j int)bool{a,b:=st.Reactions[ids[i]],st.Reactions[ids[j]];if a.CreatedAt==b.CreatedAt{return a.ID<b.ID};return a.CreatedAt<b.CreatedAt})}
 for id,w:=range st.Words{maxID("word",id);wordIDs[w.LivestreamID]=append(wordIDs[w.LivestreamID],id)};for _,ids:=range wordIDs{sort.Slice(ids,func(i,j int)bool{return ids[i]<ids[j]})}
 for id,r:=range st.Reports{maxID("report",id);reportIDs[r.LivestreamID]=append(reportIDs[r.LivestreamID],id);agg(streamStats,r.LivestreamID).Reports++};for _,ids:=range reportIDs{sort.Slice(ids,func(i,j int)bool{return ids[i]<ids[j]})}
 for lid,vs:=range st.Viewers{for _,v:=range vs{agg(streamStats,lid).Viewers+=int64(len(v));if l:=st.Streams[lid];l!=nil{agg(userStats,l.Model.UserID).Viewers+=int64(len(v))}}}
}
func indexStream(s *StreamData){id:=s.Model.ID;streamIDs=append(streamIDs,id);userStreams[s.Model.UserID]=append(userStreams[s.Model.UserID],id);for _,t:=range s.Tags{tagStreams[t.Name]=append(tagStreams[t.Name],id)};agg(streamStats,id)}
func indexComment(c LivecommentModel,sign int64){a:=agg(streamStats,c.LivestreamID);a.Comments+=sign;a.Tips+=c.Tip*sign;if sign>0&&c.Tip>a.MaxTip{a.MaxTip=c.Tip};if l:=st.Streams[c.LivestreamID];l!=nil{a=agg(userStats,l.Model.UserID);a.Comments+=sign;a.Tips+=c.Tip*sign};totalTips+=c.Tip*sign}
func indexReaction(r ReactionModel){a:=agg(streamStats,r.LivestreamID);a.Reactions++;a.Emoji[r.EmojiName]++;if l:=st.Streams[r.LivestreamID];l!=nil{a=agg(userStats,l.Model.UserID);a.Reactions++;a.Emoji[r.EmojiName]++}}
