 switch e.Kind {
 case "user":st.Users[e.User.Model.ID]=e.User;st.Names[e.User.Model.Name]=e.User.Model.ID;maxID("user",e.User.Model.ID);maxID("theme",e.User.Theme.ID);agg(userStats,e.User.Model.ID)
 case "icon":u:=st.Users[e.UserID];u.Image=e.Image;u.Hash=hash(e.Image);maxID("icon",e.ID)
 case "stream":s:=e.Stream;st.Streams[s.Model.ID]=s;maxID("stream",s.Model.ID);for i:=range st.Slots{v:=&st.Slots[i];if v.StartAt>=s.Model.StartAt&&v.EndAt<=s.Model.EndAt{v.Slot--}};indexStream(s)
 case "comment":c:=*e.Comment;st.Comments[c.ID]=c;maxID("comment",c.ID);commentIDs[c.LivestreamID]=append(commentIDs[c.LivestreamID],c.ID);indexComment(c,1)
 case "reaction":r:=*e.Reaction;st.Reactions[r.ID]=r;maxID("reaction",r.ID);reactionIDs[r.LivestreamID]=append(reactionIDs[r.LivestreamID],r.ID);indexReaction(r)
 case "report":r:=*e.Report;st.Reports[r.ID]=r;maxID("report",r.ID);reportIDs[r.LivestreamID]=append(reportIDs[r.LivestreamID],r.ID);agg(streamStats,r.LivestreamID).Reports++
 case "word":w:=*e.Word;st.Words[w.ID]=w;maxID("word",w.ID);wordIDs[w.LivestreamID]=append(wordIDs[w.LivestreamID],w.ID);for _,id:=range e.Delete{if c,ok:=st.Comments[id];ok{indexComment(c,-1);delete(st.Comments,id)}};a:=agg(streamStats,w.LivestreamID);a.MaxTip=0;for _,id:=range commentIDs[w.LivestreamID]{c:=st.Comments[id];if c.Tip>a.MaxTip{a.MaxTip=c.Tip}}
 case "enter","exit":if st.Viewers[e.StreamID]==nil{st.Viewers[e.StreamID]=map[int64][]int64{}};delta:=int64(1);if e.Kind=="enter"{st.Viewers[e.StreamID][e.UserID]=append(st.Viewers[e.StreamID][e.UserID],e.Time)}else{delta=-int64(len(st.Viewers[e.StreamID][e.UserID]));delete(st.Viewers[e.StreamID],e.UserID)};agg(streamStats,e.StreamID).Viewers+=delta;if s:=st.Streams[e.StreamID];s!=nil{agg(userStats,s.Model.UserID).Viewers+=delta}
 }
}
func record(e Event)error{b,err:=json.Marshal(e);if err!=nil{return err};b=append(b,'"'\\n');walMu.Lock();_,err=wal.Write(b);walMu.Unlock();if err"'!=nil{return err};apply(e);return nil}
func syncWAL()error{walMu.Lock();defer walMu.Unlock();return wal.Sync()}
func snapshot()error{f,e:=os.Create("state.gob.tmp");if e!=nil{return e};if e=gob.NewEncoder(f).Encode(st);e!=nil{f.Close();return e};if e=f.Sync();e!=nil{f.Close();return e};f.Close();return os.Rename("state.gob.tmp","state.gob")}
func recoverState()error{f,e:=os.Open("state.gob");if os.IsNotExist(e){if e=loadSQL();e!=nil{return e};if e=snapshot();e!=nil{return e}}else if e!=nil{return e}else{e=gob.NewDecoder(f).Decode(&st);f.Close();if e!=nil{return e};reindex()}
 f,e=os.Open("state.wal");if e==nil{r:=bufio.NewReader(f);for{line,err:=r.ReadBytes('"'\\n');if err==io.EOF{break};if err"'!=nil{return err};var ev Event;if err=json.Unmarshal(line,&ev);err!=nil{return err};apply(ev)};f.Close()}else if !os.IsNotExist(e){return e}
 wal,e=os.OpenFile("state.wal",os.O_CREATE|os.O_APPEND|os.O_WRONLY,0600);return e
}
EOF'

